#define main original_tool_main
#include "test-painter-mypaint-tool.cpp"
#undef main
static void saving_probe(){Scene s;s.motion(false);s.press();for(int i=0;i<90;++i){s.coords.x=24+i%80;s.motion(true,100);}g_print("SAVE_BEFORE active=%d preserve=%d has_image=%d depth=%d\n",gimp_tool_control_is_active(s.tool->control),gimp_tool_control_get_preserve(s.tool->control),gimp_tool_has_image(s.tool,s.image)==s.display,s.depth());gimp_image_saving(s.image);auto saved=s.pixels();g_print("SAVE_AFTER active=%d pending=%d depth=%d\n",gimp_tool_control_is_active(s.tool->control),gimp_painter_mybrush_tool_has_pending_stroke(GIMP_PAINTER_MYBRUSH_TOOL(s.tool)),s.depth());for(int i=0;i<20;++i){s.coords.x=20+i;s.coords.y=70;s.motion(true,100);}g_print("HELD_MOTION changed=%d active=%d depth=%d\n",s.pixels()!=saved,gimp_tool_control_is_active(s.tool->control),s.depth());if(gimp_tool_control_is_active(s.tool->control))s.release();gimp_image_saving(s.image);g_print("FINAL depth=%d\n",s.depth());}
int main(int argc,char**argv){g_test_init(&argc,&argv,nullptr);gimp_test_utils_set_gimp3_directory("GIMP_TESTING_ABS_TOP_SRCDIR","app/tests/gimpdir");gimp_test_utils_setup_menus_path();gimp=gimp_init_for_gui_testing(TRUE);g_object_set(gimp->config,"painter-canvas-ui",TRUE,nullptr);g_test_add_func("/physical/save-baseline",saving_probe);g_application_run(gimp->app,0,nullptr);int result=gimp_core_app_get_exit_status(GIMP_CORE_APP(gimp->app));g_application_quit(G_APPLICATION(gimp->app));g_clear_object(&gimp->app);return result;}
